  /* Wait till voltage level flag is set */
  while ((PWR->CSR1 & PWR_CSR1_ACTVOSRDY) == 0U)
  {}
#elif defined(USE_PWR_SMPS_1V8_SUPPLIES_LDO) && defined(SM

/* common_system_clock frequency : CM7 CPU frequency  */
  common_system_clock >>= tmp;

